const input = process.env.MARKDOWN_INPUT || '';
if (typeof input !== 'string' || input.length === 0) {
  throw new Error('Input markdown must be a non-empty string');
}
globalThis.markdownInput = input;

const mod = await import('marked');
const marked = mod.default || mod;
const html = marked.parse(globalThis.markdownInput);
globalThis.htmlOutput = html;

if (typeof globalThis.htmlOutput !== 'string' || globalThis.htmlOutput.trim().length === 0) {
  throw new Error('Parsed HTML is empty or invalid');
}
globalThis.finalHtml = globalThis.htmlOutput.trim();
